class EBike {
}

class Frame {
  + material : string
}

class DriveSystem {
}

class Motor {}

class Controller {
  + state : ControllerState
}

abstract class AdvancedController extends Controller {
  + nextInspectionDate : date
}

class BasicController extends Controller {}

class Battery {
  + storedEnergy : double
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
